// Algorithmen: zwei Lernkapitel, Zusammenfassung, drei Übungsbereiche und gemeinsamer Test
const algoGeneralSlides=[{"title": "Algorithmen begegnen dir überall", "body": "Ein Rezept, eine Bauanleitung und das Zähneputzen bestehen aus Schritten, die ein Ziel erreichen. Auch ohne Computer kannst du Algorithmen ausführen.", "visual": "🍳 → 🥣 → 🥞"}, {"title": "Was ist ein Algorithmus?", "body": "Ein Algorithmus ist eine genaue Folge von Anweisungen, mit der eine Aufgabe gelöst wird. Er muss eindeutig, ausführbar und endlich sein. Dazu gehört eine feste, sinnvolle Reihenfolge: Die Anweisungen werden Schritt für Schritt ausgeführt.", "visual": "1 → 2 → 3 → Ziel"}, {"title": "Was ist kein Algorithmus?", "body": "„Mach irgendetwas Schönes“ ist unklar. „Nimm ein Blatt, zeichne einen Kreis und male ihn aus“ beschreibt dagegen konkrete Schritte.", "visual": "❓  →  ✅"}, {"title": "Wissenscheck", "question": "Welche Anweisung ist eindeutig?", "choices": ["Mach etwas Leckeres.", "Lege zwei Scheiben Brot auf einen Teller.", "Mach schnell!"], "answer": 1, "hint": "Überlege, welche Regel du gelernt hast.", "why": "Diese Antwort passt zur Erklärung."}, {"title": "Eindeutigkeit: klare Anweisungen", "body": "Jede Anweisung muss klar verständlich sein. Wer den Algorithmus ausführt, darf nicht raten müssen, was gemeint ist.", "visual": "🔎 Klar statt ungenau"}, {"title": "Ausführbarkeit: sinnvolle Schritte", "body": "Jede Anweisung muss sinnvoll und tatsächlich ausführbar sein. Beim Pfannkuchenmachen werden Eier zuerst aufgeschlagen und nicht mit Schale in den Teig gegeben. Ein Ablauf muss außerdem eindeutig und endlich sein.", "visual": "🛠️ Kann ich das tun?", "sub": "Eine der drei Bedingungen eines Algorithmus"}, {"title": "Endlichkeit: ein erreichbares Ende", "body": "Ein Algorithmus muss nach endlich vielen Schritten enden. Er benötigt ein klares Ziel und eine Möglichkeit, fertig zu werden.", "visual": "🏁 Start → Schritte → Ende"}, {"title": "Wissenscheck", "question": "Welche Eigenschaft fehlt bei „Wiederhole für immer“?", "choices": ["Eindeutigkeit", "Endlichkeit", "Ausführbarkeit"], "answer": 1, "hint": "Überlege, welche Regel du gelernt hast.", "why": "Diese Antwort passt zur Erklärung."}, {"title": "Anweisungen in richtiger Reihenfolge", "body": "Beim Teekochen brauchst du mehrere klare Schritte: Wasser in den Wasserkocher füllen, Wasser erhitzen, einen Teebeutel in eine Tasse legen, heißes Wasser eingießen und den Tee ziehen lassen. Formuliere dafür mindestens fünf klare Schritte.", "visual": "① Wasser  ② Einschalten  ③ Aufgießen"}, {"title": "Die Sequenz", "body": "Eine Sequenz ist eine feste Folge von Anweisungen. Zeichne eine Sequenz für deinen Schulweg ins Heft: Beginne zu Hause, beschreibe mindestens vier eindeutige Schritte und ende an der Schule. Nutze sichere bekannte Wege und markierte Übergänge.", "visual": "A → B → C"}, {"title": "Algorithmen prüfen", "body": "Prüfe drei Bedingungen: Sind Anweisungen und Reihenfolge eindeutig? Ist jeder Schritt sinnvoll ausführbar? Hat der Ablauf ein klares Ende? Gehe dazu Schritt für Schritt durch die Anleitung.", "visual": "✓ eindeutig  ✓ ausführbar  ✓ endlich"}, {"title": "Wissenscheck", "question": "Was ist eine Sequenz?", "choices": ["Eine zufällige Auswahl", "Eine Abfolge von Anweisungen", "Ein Computerbauteil"], "answer": 1, "hint": "Überlege, welche Regel du gelernt hast.", "why": "Diese Antwort passt zur Erklärung."}, {"title": "Fehlerdetektiv", "body": "Beim Schuheanziehen kommt zuerst die Socke und dann der Schuh. Wenn du Schritte vertauschst, kann der Ablauf scheitern.", "visual": "🧦 → 👟"}, {"title": "Algorithmen selbst entwickeln", "body": "Zerlege eine Aufgabe in kleine Schritte. Formuliere jeden Schritt als klare Handlungsanweisung und überprüfe die Reihenfolge.", "visual": "📝 Planen → Prüfen → Verbessern"}, {"title": "Wissenscheck", "question": "Welche Anleitung ist am besten?", "choices": ["Bereite etwas vor.", "Mach das irgendwann.", "Stelle die Tasse hin und lege einen Teebeutel hinein."], "answer": 2, "hint": "Überlege, welche Regel du gelernt hast.", "why": "Diese Antwort passt zur Erklärung."}, {"title": "Händewaschen: klare Befehle", "body": "Betrachte die Bilder A bis E. Beschreibe mündlich zu jedem Bild eine klare Anweisung in der Befehlsform. Erkläre anschließend einem Partner, warum die Reihenfolge sinnvoll ist.", "visual": "A → B → C → D → E"}, {"title": "Du kannst Algorithmen erkennen!", "body": "Du kennst Definition, Eigenschaften und Sequenzen. Jetzt kannst du eigene Anweisungsfolgen prüfen und verbessern.", "visual": "🏆"}];
const algoDisplaySlides=[{"title": "Warum Algorithmen darstellen?", "body": "Ein Ablaufplan zeigt eine Anweisungsfolge übersichtlich. Pfeile zeigen, in welcher Reihenfolge die Schritte ausgeführt werden.", "visual": "Start ↓ Aktion ↓ Ende"}, {"title": "Ein einfacher Ablaufplan", "body": "Lies das vollständige Zähneputzen-Beispiel von oben nach unten: Zwischen Start und Ende stehen sechs Aktionen. Jede Aktion hat ein eigenes Rechteck; die Pfeile legen ihre Reihenfolge fest. „3 Minuten putzen“ ist hier eine Anweisung im Beispiel.", "visual": "(Start) → [Schritt 1] → [Schritt 2] → (Ende)"}, {"title": "Das Oval", "body": "Das Oval steht für Start oder Ende. Jeder vollständige Ablauf braucht einen Startpunkt und einen Endpunkt.", "visual": "⬭ Start     ⬭ Ende"}, {"title": "Das Rechteck", "body": "Im Rechteck steht eine Aktion: zum Beispiel „Zahnbürste nehmen“. Eine Aktion pro Rechteck ist besonders übersichtlich.", "visual": "▭ Zahnbürste nehmen"}, {"title": "Wissenscheck", "question": "Welches Symbol steht für eine Aktion?", "choices": ["Oval", "Rechteck", "Raute"], "answer": 1, "hint": "Überlege, welche Regel du gelernt hast.", "why": "Diese Antwort passt zur Erklärung."}, {"title": "Die Pfeile", "body": "Pfeile verbinden die Symbole und legen die Richtung des Ablaufs fest. Ohne Pfeile ist die Reihenfolge unklar.", "visual": "⬭ ↓ ▭ ↓ ▭ ↓ ⬭"}, {"title": "Die Raute", "body": "Eine Raute stellt eine Entscheidung dar. Darin steht eine Frage, die mit Ja oder Nein beantwortet wird.", "visual": "◇ Regnet es? ◇"}, {"title": "Wenn – dann – sonst", "body": "Wenn es regnet, nimm einen Regenschirm mit. Sonst nimm eine Sonnenbrille mit. Beide Wege führen anschließend zur Aktion „Zur Schule gehen“ und dann zum Ende. Die Frage in der Raute wird mit Ja oder Nein beantwortet.", "visual": "◇ Regnet es? → Ja: ☂️ / Nein: 🕶️"}, {"title": "Wissenscheck", "question": "Wie viele Ausgänge hat eine Ja/Nein-Entscheidung?", "choices": ["Einen", "Zwei", "Vier"], "answer": 1, "hint": "Überlege, welche Regel du gelernt hast.", "why": "Diese Antwort passt zur Erklärung."}, {"title": "Flussdiagramme lesen", "body": "Beginne beim Start und folge den Pfeilen bis zum Ende. Zähle nur die Rechtecke als Aktionen: Das Zähneputzen-Diagramm hat sechs Aktionen. Start und Ende werden nicht mitgezählt. Bei einer Raute wählst du den passenden Ja- oder Nein-Weg.", "visual": "Start → Frage → Weg → Ende"}, {"title": "Flussdiagramme zeichnen", "body": "Beginne mit dem Oval „Start“ und beende den Ablauf mit dem Oval „Ende“. Jede Aktion bekommt ein eigenes Rechteck. Verbinde die Symbole mit Pfeilen. Erstelle einen Ablaufplan zum Thema „Einen Schulranzen für morgen packen“ mit mindestens vier Aktionen. Wenn du Entscheidungen verwendest, beschrifte die Wege mit Ja und Nein.", "visual": "⬭  ▭  ◇  →"}, {"title": "Schleifen: etwas wiederholen", "body": "Eine Schleife wiederholt einen oder mehrere Schritte. Ein Beispiel: Prüfe „Aufgaben fertig?“. Bei Nein löse eine Aufgabe und prüfe erneut. Bei Ja gehe spielen und beende den Ablauf. Der Rückpfeil zeigt zur erneuten Prüfung, nicht zum Ende.", "visual": "🔁 Wiederholen bis fertig"}, {"title": "Zählschleife und Bedingungsschleife", "body": "Zählschleife: Wiederhole zehnmal „Hampelmann machen“. Du weißt vorher, wie oft. Bedingungsschleife: Solange das Glas nicht voll ist, gieße weiter Wasser ein. Hier steht die Anzahl der Wiederholungen vorher nicht fest.", "visual": "5-mal 🔁  |  solange … 🔁"}, {"title": "Wissenscheck", "question": "Was ist eine Schleife?", "choices": ["Ein einmaliger Start", "Eine Wiederholung von Schritten", "Ein anderes Wort für Software"], "answer": 1, "hint": "Überlege, welche Regel du gelernt hast.", "why": "Diese Antwort passt zur Erklärung."}, {"title": "Darstellungen sicher verstehen", "body": "Du kannst Ablaufpläne lesen und zeichnen: Sequenzen, Entscheidungen und Wiederholungen. Prüfe Start und Ende, die Symbole und die beschrifteten Pfeile.", "visual": "🎯"}];
const algoSummarySlides=[{"title": "Das Wichtigste zu Algorithmen", "body": "Ein Algorithmus muss eindeutig, ausführbar und endlich sein. Die Anweisungen sind klar und stehen in einer sinnvollen Reihenfolge. Eine solche Schrittfolge heißt Sequenz.", "visual": "Eindeutig · Ausführbar · Endlich"}, {"title": "Symbole und Pfeile", "body": "Oval: Start/Ende. Rechteck: Aktion. Raute: Ja/Nein-Entscheidung. Pfeile: Reihenfolge.", "visual": "⬭   ▭   ◇   →"}, {"title": "Drei Ablaufarten", "body": "Sequenz: nacheinander. Verzweigung: abhängig von einer Bedingung. Schleife: Schritte wiederholen.", "visual": "→   ◇   🔁"}, {"title": "Bereit für den Test?", "body": "Prüfe die Begriffe, ordne Schritte und Symbole zu und übe auch die Anwendung an neuen Beispielen.", "visual": "🏁"}];
